const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function getInfoAsync(obj) {
  return await new Promise((resolve, reject) => {
    obj.getInfo((res, err) => {
      if (err) reject(err);
      else resolve(res);
    });
  });
}

function makeWindow(baseDateStr, padDays) {
  const start = ee.Date(baseDateStr).advance(-padDays, 'day');
  const end = ee.Date(baseDateStr).advance(padDays + 1, 'day'); // end is exclusive
  return { start: start, end: end };
}

function getCollection(sensorId, geom, start, end) {
  return ee.ImageCollection(sensorId)
    .filterBounds(geom)
    .filterDate(start, end);
}

function buildCloudMaskFromQAPixel(img) {
  const qa = img.select('QA_PIXEL');
  const fill = qa.bitwiseAnd(1).neq(0);
  const valid = fill.not();
  const dilated = qa.bitwiseAnd(1 << 1).neq(0);
  const cirrus = qa.bitwiseAnd(1 << 2).neq(0);
  const cloud = qa.bitwiseAnd(1 << 3).neq(0);
  const isCloud = dilated.or(cirrus).or(cloud);
  return { valid: valid, isCloud: isCloud };
}

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const roi = ee.Geometry.Point([-49.053062, -1.593993]).buffer(100000); // 100 km
    const baseDate = '2009-08-19';
    const windows = [0, 3, 7]; // same day, ±3 days, ±7 days
    const sensors = [
      { id: 'LANDSAT/LT05/C02/T1_L2', name: 'LT05' },
      { id: 'LANDSAT/LE07/C02/T1_L2', name: 'LE07' }
    ];

    // 2. Data Acquisition & Check with fallback
    let chosen = null;
    let chosenCol = null;
    for (let w of windows) {
      const win = makeWindow(baseDate, w);
      for (let s of sensors) {
        const col = getCollection(s.id, roi, win.start, win.end);
        const sz = await getInfoAsync(col.size());
        if (sz > 0) {
          chosen = { sensor: s.name, sensorId: s.id, start: await getInfoAsync(win.start.format('YYYY-MM-dd')), end: await getInfoAsync(win.end.format('YYYY-MM-dd')), size: sz, padDays: w };
          chosenCol = col;
          break;
        }
      }
      if (chosen) break;
    }
    if (!chosen) {
      console.log('Selected: None');
      console.log('Reason: No images found for date/location (after fallbacks).');
      console.log('C1: Empty Collection');
      return;
    }
    console.log('Selected:', chosen.sensor, 'Win:', chosen.start, 'to', chosen.end, 'Images:', chosen.size);

    // 3. Build mosaic image (keep QA_PIXEL for cloud flags)
    const mosaic = chosenCol.sort('CLOUD_COVER').mosaic().clip(roi);

    // 4. Water (river) vs Land masks using JRC Global Surface Water occurrence
    const gsw = ee.Image('JRC/GSW1_4/GlobalSurfaceWater').select('occurrence');
    const waterMask = gsw.gt(50); // >50% occurrence as river/water
    const landMask = waterMask.not();

    // 5. Cloud detection using QA_PIXEL
    const qaBands = buildCloudMaskFromQAPixel(mosaic);
    const valid = qaBands.valid;
    const isCloud = qaBands.isCloud;

    // Valid masks per class
    const validWater = valid.and(waterMask);
    const validLand = valid.and(landMask);

    // 6. Counts at coarse scale to avoid timeout
    const scale = 1500; // meters
    const ones = ee.Image.constant(1).toInt();

    const waterCountImg = ones.updateMask(validWater);
    const waterCloudCountImg = ones.updateMask(validWater.and(isCloud));

    const landCountImg = ones.updateMask(validLand);
    const landCloudCountImg = ones.updateMask(validLand.and(isCloud));

    const waterDict = waterCountImg.addBands(waterCloudCountImg.rename('cloud'))
      .reduceRegion({
        reducer: ee.Reducer.sum().repeat(2).setOutputs(['total', 'cloud']),
        geometry: roi, scale: scale, maxPixels: 1e9, tileScale: 2
      });

    const landDict = landCountImg.addBands(landCloudCountImg.rename('cloud'))
      .reduceRegion({
        reducer: ee.Reducer.sum().repeat(2).setOutputs(['total', 'cloud']),
        geometry: roi, scale: scale, maxPixels: 1e9, tileScale: 2
      });

    const waterStats = await getInfoAsync(waterDict);
    const landStats = await getInfoAsync(landDict);

    const wTotal = waterStats ? waterStats.total : null;
    const wCloud = waterStats ? waterStats.cloud : null;
    const lTotal = landStats ? landStats.total : null;
    const lCloud = landStats ? landStats.cloud : null;

    // 7. Validation for C2/C3
    if (!wTotal || !lTotal || wTotal === 0 || lTotal === 0) {
      console.log('Valid Pixels - Water:', wTotal || 0, 'Land:', lTotal || 0);
      console.log('C2: No Valid Pixels');
      return;
    }

    const wFrac = wCloud / wTotal;
    const lFrac = lCloud / lTotal;

    const invalid = [wFrac, lFrac].some(v => v === null || v === undefined || isNaN(v) || v < 0 || v > 1);
    if (invalid) {
      console.log('Calculation invalid. wFrac:', wFrac, 'lFrac:', lFrac);
      console.log('C3: Calculation Failure');
      return;
    }

    // 8. Print concise stats
    const cloudAllDict = ones.updateMask(valid.and(isCloud)).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: roi, scale: scale, maxPixels: 1e9, tileScale: 2
    });
    const totalAllDict = ones.updateMask(valid).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: roi, scale: scale, maxPixels: 1e9, tileScale: 2
    });
    const cloudAll = await getInfoAsync(cloudAllDict).then(d => d.sum || 0);
    const totalAll = await getInfoAsync(totalAllDict).then(d => d.sum || 0);
    const allFrac = totalAll > 0 ? (cloudAll / totalAll) : null;

    console.log('Water Pixels:', wTotal, 'Cloud:', wCloud, 'Cloud%:', (wFrac * 100).toFixed(1));
    console.log('Land  Pixels:', lTotal, 'Cloud:', lCloud, 'Cloud%:', (lFrac * 100).toFixed(1));
    if (allFrac !== null) {
      console.log('Overall Cloud% (valid area):', (allFrac * 100).toFixed(1));
    }
    console.log('Water mask: GSW occurrence > 50%');
    console.log('Cloud bits: QA_PIXEL (Dilated | Cirrus | Cloud)');

    // 9. Final Answer
    if (lFrac > wFrac) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log('Error:', (err && err.message) ? err.message : String(err));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
